const crypto = require('crypto');

function stableStringify(v) {
  if (v === null || v === undefined) return 'null';
  const t = typeof v;
  if (t === 'number' || t === 'boolean') return JSON.stringify(v);
  if (t === 'string') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
  if (t === 'object') {
    const keys = Object.keys(v).sort();
    return '{' + keys.map((k) => JSON.stringify(k) + ':' + stableStringify(v[k])).join(',') + '}';
  }
  return JSON.stringify(String(v));
}

const sectorEnv = String($env.SECTOR_ID || '').trim();
if (!sectorEnv) {
  return [];
}

const row = $input.first().json;
const h = row.h != null ? Number(row.h) : null;
const t = row.t != null ? Number(row.t) : null;
const sector = row.sector_id != null ? String(row.sector_id).trim() : sectorEnv;

if (sector !== sectorEnv) {
  return [];
}

let diag = 'Normal';
let crit = false;
if (h != null && t != null && h < 25 && t > 35) {
  diag = 'Estres hidrico critico (umbral demo, ventana 5 min)';
  crit = true;
}

const decision = crit ? '[CRITICAL] ' + diag : diag;
const confianza = crit ? 72 : h != null && t != null ? 90 : 55;

const coreId = String($env.CORE_ID || 'nucleo-alpha').trim() || 'nucleo-alpha';
const sectorTag = sectorEnv.replace(/\s+/g, '-');
const tags = ['#ia-decision', '#sector-' + sectorTag];

const auditBody = {
  kind: 'ia',
  agente_id: coreId,
  actor: coreId,
  decision,
  confianza,
  tags,
  contexto:
    'DIAGNOSTICO_IA sector=' +
    sector +
    ' humedad=' +
    h +
    ' temp=' +
    t +
    ' criticidad=' +
    (crit ? 'CRITICAL' : 'OK'),
  status: crit ? 'CRITICAL' : 'OK',
  event: 'DIAGNOSTICO_IA',
  details: {
    sector_id: sector,
    humedad: h,
    temp: t,
    tipo_evento: 'DIAGNOSTICO_IA',
    ventana_minutos: 5,
    core_id: coreId
  }
};

const secret = String($env.CASTUO_AUDIT_WEBHOOK_SECRET || '').trim();
let signature = '';
if (secret) {
  signature = crypto.createHmac('sha256', secret).update(stableStringify(auditBody), 'utf8').digest('hex');
}

return [
  {
    json: {
      auditBody,
      hmacSignature: signature,
      hmacRequired: !!secret,
      auditUrl: String($env.CASTUO_TRILLIZO_AUDIT_URL || 'http://n8n-trillizo:5678/webhook/audit-trigger')
    }
  }
];
